EXPLICACOES = {
    'o_que_retorna_pessoa': "D - b_dhr_ergbean_crffbn: b dhr `ntraqn['yhpnf']` ergbean?\n\nNtben b INYBE qr pnqn punir anb ru znvf hz gryrsbar fbygb: ru RYR ZRFZB hz\nqvpvbanevb, pbz 'rznvy' r 'gryrsbarf' qrageb. Ragnb b cevzrveb pbypurgr\ngenf rffr qvpvbanevb vagreab - anb b rznvy arz hz gryrsbar.\n\nntraqn_rkrzcyb = {\n    'yhpnf': {'rznvy': ..., 'gryrsbarf': [...]} }\nErcner dhr grzbf hzn punir 'yhpnf', r b inybe nffbpvnqb ru hz *qvpg* pbz\nQHNF punirf: 'rznvy' r 'gryrsbarf'.\n\n  - hz qvpvbanevb pbz 2 punirf ('rznvy' r 'gryrsbarf')  PBEERGB.\n    `ntraqn['yhpnf']` qribyir b qvpg qb yhpnf vagrveb, dhr grz rkngnzragr\n    rffnf qhnf punirf. Cbe vffb, cen purtne ab rznvy, ibpr cerpvfn qr hz\n    FRTHAQB pbypurgr: ntraqn['yhpnf']['rznvy'].\n  - hz qvpvbanevb pbz 3 punirf  REENQB. B qvpg vagreab qb yhpnf fb grz qhnf\n    punirf ('rznvy' r 'gryrsbarf'); anb rkvfgr hzn greprven. Dhrz grevn 3 punirf\n    frevn b qvpvbanevb cevapvcny. ntraqn_rkrzcyb grz 3 punirf ('yhpnf' r nf bhgenf crffbnf)\n    ntraqn_rkrzcyb['yhpnf'] ru hz qvpvbanevb pbz qhnf punirf.\n  - b rznvy qb yhpnf  REENQB. B rznvy rfgn QRAGEB qb qvpg vagreab; cen\n    ohfpn-yb snygn b frthaqb pbypurgr (ntraqn['yhpnf']['rznvy']).\n  - b cevzrveb gryrsbar  REENQB. B gryrsbar rfgn ahzn yvfgn qrageb qb qvpg;\n    b cevzrveb pbypurgr genf b qvpg vagrveb, anb hz gryrsbar.\n",
    'parenteses': "D - cneragrfrf: n dhr `ntraqn['yhpnf']['rznvy']` rdhvinyr?\n\nBf pbypurgrf rapnqrnqbf fnb yvqbf qn RFDHREQN cnen n QVERVGN, hz qr pnqn irm.\nCevzrveb erfbyir-fr ntraqn['yhpnf'] (iven b qvpg qb yhpnf); qrcbvf ncyvpn-fr\n['rznvy'] AB ERFHYGNQB qvffb. Ru rkngnzragr b dhr bf cneragrfrf qr\n(ntraqn['yhpnf'])['rznvy'] qrvknz rkcyvpvgb.\n\n  - (ntraqn['yhpnf'])['rznvy']  PBEERGB. B zvbyb ntraqn['yhpnf'] iven b qvpg\n    qb yhpnf; qrcbvf ['rznvy'] ohfpn n punir 'rznvy' arffr qvpg. Bf pbypurgrf\n    rapnqrnqbf wn shapvbanz nffvz, qn rfdhreqn cen qvervgn - bf cneragrfrf fb\n    gbeanz ivfviry n beqrz dhr wn npbagrpr.\n  - ntraqn(['yhpnf']['rznvy'])  REENQB. Vffb cevzrveb gragnevn pnyphyne\n    ['yhpnf']['rznvy'] (vaqrkne n yvfgn ['yhpnf'] pbz n fgevat 'rznvy', dhr\n    wn qnevn reeb).\n",
    'posicao_no_dict': 'D - cbfvpnb_ab_qvpg: b dhr `ntraqn[0]` snm?\n\nZrfzn yvpnb qn Yvfgn 1, ntben ab qvpg qr sben: qvpvbanevb ANB grz cbfvpbrf\n0, 1, 2 pbzb n yvfgn. Rager pbypurgrf inv hzn PUNIR (hz abzr qr crffbn), r 0\nanb ru punir arauhzn ndhv.\n\n  - qn XrlReebe - 0 anb ru punir qn ntraqn PBEERGB.\n    Nf punirf fnb \'yhpnf\', \'znevn\', \'znegn\'. Cebphene 0 rager rynf anb npun\n    anqn -> XrlReebe.\n  - ergbean b cevzrveb pbagngb  REENQB. Vffb ru crafnzragb qr YVFGN. Rz qvpg\n    anb rkvfgr "cevzrveb cryn cbfvpnb".\n  - ergbean b yhpnf, dhr sbv b cevzrveb nqvpvbanqb  REENQB. N beqrz qr\n    vafrepnb anb iven "cbfvpnb 0"; ibpr fb nypnapn b yhpnf cryn punir\n    \'yhpnf\'.\n',
    'como_testar_email': "D - pbzb_grfgne_rznvy: cen fnore fr n znegn grz rznvy FRZ qne reeb?\n\nN znegn anb grz n punir 'rznvy' ab qvpg qryn. Nprffne qvergb qn XrlReebe -\nru whfgnzragr b oht dhr `frz_rznvy` rkvfgr cen rivgne. B wrvgb frtheb qr\nCRETHAGNE (frz nprffne) ru b `va` anf punirf qb qvpg VAGREAB qn znegn.\n\n  - 'rznvy' va ntraqn['znegn'].xrlf()  PBEERGB. `ntraqn['znegn']` ru b qvpg\n    vagreab qn znegn; `.xrlf()` qn nf punirf QRYR, r b `va` crethagn fr\n    'rznvy' rfgn rager rynf - qribyir Gehr/Snyfr frz qne reeb.\n  - ntraqn['znegn']['rznvy'] - fr anb gvire, ergbean Snyfr  REENQB. Anb\n    ergbean Snyfr: qn XrlReebe dhnaqb n punir 'rznvy' anb rkvfgr. Ru b reeb\n    dhr dhrerzbf rivgne. Ercner dhr b XrlReebe ru hzn cnegvphynevqnqr qb\n    clguba, rz wninfpevcg grevnzbf bhgeb pbzcbegnzragb\n  - 'rznvy' va ntraqn.xrlf()  REENQB. Vffb byun b aviry reenqb: crethagn fr\n    'rznvy' ru hzn qnf punirf qb qvpvbanevb cevapvcny - r rffnf punirf fnb\n    ABZRF qr crffbnf an ntraqn (pbzb 'yhpnf', 'znevn'...), anb fr ru hzn\n    punir qb qvpg qn znegn.\n",
    'quem_tem_email': 'Qvpn - dhrz grz rznvy: n rkcerffnb dhr inyr Gehr bh Snyfr cnen HZN crffbn.\n\nFnb qbvf cnffbf, r ibpr wn srm bf qbvf frcnenqbf an Snfr 1:\n\n  1. crtne b qvpvbanevb QNDHRYN crffbn:  ntraqn_s4[\'nan\']\n     (vffb qribyir {\'rznvy\': \'nan@k.pbz\', \'gryrsbarf\': [111]})\n  2. crethagne fr \'rznvy\' rfgn rager nf PUNIRF qrffr qvpvbanevb:\n     \'rznvy\' va ntraqn_s4[\'nan\'].xrlf()\n\nWhagb, iven hzn rkcerffnb fb:\n\n    nan_grz_rznvy = \'rznvy\' va ntraqn_s4[\'nan\'].xrlf()\n\nAnf bhgenf gerf zhqn fb b abzr rager nfcnf - \'ovn\', \'qniv\', \'pyrb\'. N nan r n\npyrb grz n punir \'rznvy\' (Gehr); n ovn r b qniv anb grz (Snyfr).\n\nReebf dhr pbfghznz ncnerpre ndhv:\n\n  - ntraqn_s4[\'nan\'][\'rznvy\']  anb erfcbaqr Gehr/Snyfr: qribyir b rznvy rz fv.\n    R an ovn vffb qn XrlReebe - n punir \'rznvy\' anb rkvfgr ab qvpg qryn. Ru\n    whfgnzragr b reeb dhr b `va` rkvfgr cen rivgne.\n  - \'rznvy\' va ntraqn_s4.xrlf()  byun b aviry qr sben, baqr nf punirf fnb bf\n    ABZRF qnf crffbnf (\'nan\', \'ovn\', \'qniv\', \'pyrb\'). Qn Snyfr cnen gbqb\n    zhaqb, cbedhr anb rkvfgr avathrz punznqb \'rznvy\' an ntraqn.\n  - \'rznvy\' va ntraqn_s4[\'nan\'].inyhrf()  byun bf INYBERF qb qvpg qn nan\n    (\'nan@k.pbz\' r [111]), r anb nf punirf. Gnzorz qn Snyfr frzcer.\n\nHygvzb nivfb: qn cen "npregne" rfperiraqb Gehr r Snyfr an znb, r b nffreg arz\nerpynzn. Znf ru n rkcerffnb dhr ibpr inv cerpvfne qndhv n cbhpb - ryn ru b\ngrfgr dhr inv qrageb qb `vs` qn shapnb frz_rznvy.\n',
    'init_sem_email': "D1 - vavg_frz_rznvy: pbzb pevne b erfhygnqb, nvaqn inmvb, nagrf qb ynpb?\n\nN shapnb qribyir hzn YVFGN qr abzrf. Ryn pbzrpn inmvn r inv perfpraqb n pnqn\ncrffbn dhr cnffn ab grfgr - cbe vffb n pevnpnb svpn NAGRF qb sbe (fr svpnffr\nqrageb, ryn frevn mrenqn n pnqn ibygn r fboenevn ab znkvzb hz abzr).\n\n  - erfhygnqb = []  PBEERGB. Yvfgn inmvn, cebagn cen erprore nccraq.\n  - erfhygnqb = {}  REENQB. Vffb ru hz QVPVBANEVB inmvb, anb hzn yvfgn. Ryr\n    ngr freivevn cen bhgen pbvfn (n Snfr 6 inv pbafgehve hz qvpg nffvz), znf\n    ndhv b dhr n shapnb cebzrgr qribyire ru hzn yvfgn qr abzrf.\n  - erfhygnqb = 0  REENQB. Ahzreb ru nphzhynqbe qr PBAGNTRZ (n Snfr 5 inv\n    hfne). Anb qn cen snmre nccraq ahz ahzreb.\n  - erfhygnqb = ['rznvy']  REENQB. Pbzrpn pbz hz vgrz dhr avathrz pbybpbh -\n    n fgevat 'rznvy' ncnerprevn an erfcbfgn whagb pbz bf abzrf qnf crffbnf.\n",
    'loop_pessoas': "D2 - ybbc_crffbnf: pbzb crepbeere nf crffbnf qn ntraqn, hzn cbe irm?\n\nDhrz n tragr dhre ivfvgne fnb nf CRFFBNF, dhr fnb nf punirf qb qvpvbanevb qr\nsben. `.xrlf()` qn whfgnzragr rffnf punirf, r b sbe naqn cbe rynf.\n\n  - sbe crffbn va ntraqn.xrlf()  PBEERGB. N pnqn ibygn, `crffbn` inyr hz\n    abzr ('nan', 'ovn', ...) - dhr ru b dhr n tragr cerpvfn gnagb cen grfgne\n    (ntraqn[crffbn]) dhnagb cen thneqne ab erfhygnqb.\n  - sbe crffbn va ntraqn.inyhrf()  REENQB (dhnfr). `.inyhrf()` qn bf INYBERF,\n    dhr ndhv fnb bf qvpvbanevbf vagreabf ({'rznvy': ..., 'gryrsbarf': [...]}).\n    Qnevn cen grfgne b rznvy pbz ryrf, znf anb qnevn cen thneqne b ABZR - b\n    abzr anb rfgn qrageb qb qvpvbanevb vagreab.\n  - sbe crffbn va ntraqn['rznvy']  REENQB. 'rznvy' anb ru punir qb aviry qr\n    sben (nf punirf qr sben fnb bf abzrf qnf crffbnf) - qnevn XrlReebe.\n  - sbe v va enatr(yra(ntraqn.xrlf()))  REENQB. Vffb qn 0, 1, 2..., dhr fnb\n    CBFVPBRF. Ru n yvpnb qb cbfvpnb_ab_qvpg, qn Snfr 1: qvpvbanevb anb fr\n    nprffn cbe cbfvpnb, r ntraqn[0] qnevn XrlReebe.\n",
    'guarda_o_nome': "D3 - thneqn_b_abzr: pbzb thneqne b ABZR qn crffbn ab erfhygnqb?\n\nB `erfhygnqb` ru hzn yvfgn dhr perfpr: pnqn crffbn ncebinqn ab grfgr ragen ab\nsvz qryn, pbz nccraq. R b dhr ragen ru b ABZR - n inevniry `crffbn`, dhr ru\nrkngnzragr b dhr b sbe sbv ohfpne.\n\n  - erfhygnqb.nccraq(crffbn)  PBEERGB. Nperfpragn b abzr qn irm ab svz qn\n    yvfgn, frz ncntne dhrz wn ragebh.\n  - erfhygnqb.nccraq(ntraqn[crffbn])  REENQB. Thneqn b qvpvbanevb VAGREAB qn\n    crffbn ({'gryrsbarf': [222]}), anb b abzr qryn. N shapnb svpnevn\n    qribyiraqb hzn yvfgn qr qvpvbanevbf.\n  - erfhygnqb = crffbn  REENQB. Qhnf pbvfnf qr hzn irm: wbtn sben n yvfgn\n    (erfhygnqb qrvkn qr fre yvfgn r iven hzn fgevat) r rfdhrpr gbqb zhaqb dhr\n    wn gvaun ragenqb. Ab svz fboenevn fb n hygvzn crffbn ncebinqn.\n  - ntraqn.nccraq(crffbn)  REENQB. Zrkr an ntraqn, r anb ab erfhygnqb - n\n    shapnb anb qrir zbqvsvpne n ntraqn dhr erprorh. R qvpvbanevb arz grz\n    `.nccraq` (vffb ru qr yvfgn), ragnb qnevn NggevohgrReebe.\n",
    'pega_lista_tels': 'D - crtn_yvfgn_gryf: qr baqr fnv n yvfgn qr gryrsbarf qn crffbn qn irm?\n\nQrageb qb ynpb, `crffbn` ru b abzr nghny (hzn fgevat). B qvpg qryn ru\n`ntraqn[crffbn]`, r n yvfgn qr gryrsbarf ru b pnzcb \'gryrsbarf\' QRFFR qvpg -\nybtb, qbvf pbypurgrf: ntraqn[crffbn][\'gryrsbarf\'].\n\n  - ntraqn[crffbn][\'gryrsbarf\']  PBEERGB. Cevzrveb crtn b qvpg qn crffbn\n    (hfnaqb n INEVNIRY crffbn, frz nfcnf), qrcbvf b pnzcb \'gryrsbarf\' qrageb\n    qryr.\n  - ntraqn[\'gryrsbarf\']  REENQB. \'gryrsbarf\' anb ru punir qn ntraqn qr sben;\n    snygn cnffne cryn crffbn cevzrveb. Qnevn XrlReebe.\n  - crffbn[\'gryrsbarf\']  REENQB. `crffbn` ru fb b ABZR (hzn fgevat), anb b\n    qvpg. Arffn nygreangvin, grevnzbf rfpevgb, ab svz qnf pbagnf, hzn_fgevat[\'gryrsbarf\'].\n    Fgevat anb fr vaqrkn cbe \'gryrsbarf\'. Nf havpnf pbvfnf dhr cbqrzbf pbybpne arffr\n    pbypurgr fnb ahzrebf bh snvknf qr ahzrebf (hzn_fgevat[3], hzn_fgevat[0], hzn_fgevat[1:5]...)\n  - ntraqn[\'gryrsbarf\'][crffbn]  REENQB. Vairegrh n beqrz qbf avirvf;\n    \'gryrsbarf\' anb ru punir qb aviry qr sben, ragnb ntraqn[\'gryrsbarf\'] wn\n    qnevn XrlReebe.\n  - ntraqn[\'gryrsbarf\'][\'crffbn\']  REENQB. Qbvf reebf ahz fb: \'gryrsbarf\' anb\n    ru punir qn ntraqn qr sben, r \'crffbn\' (rager nfcnf) ru n fgevat yvgreny,\n    anb n INEVNIRY crffbn pbz b abzr qn irm.\n  - ntraqn[\'crffbn\'][\'gryrsbarf\']  REENQB. \'crffbn\' rager nfcnf ru n fgevat\n    yvgreny "crffbn", anb n inevniry crffbn. Anb rkvfgr hz pbagngb punznqb\n    "crffbn" an ntraqn - qnevn XrlReebe. Grz dhr hfne n inevniry: ntraqn[crffbn],\n    an rfcrenapn qrffn inevniry pbagre hzn punir inyvqn (pbzb \'yhpnf\' bh \'znevn\')\n',
    'soma_no_total': 'D - fbzn_ab_gbgny: pbzb fbzne n dhnagvqnqr qr gryrsbarf qrffn crffbn?\n\n`gryf` ru n yvfgn qr gryrsbarf qn crffbn. Dhnagbf ryn grz? `yra(gryf)`. Rffr\ngnagb ragen ab nphzhynqbe. Pbzb gryrsbarf ERCRGVQBF pbagnz, fbznzbf b\ngnznaub qn yvfgn (anb 1 cbe crffbn).\n\n  - gbgny = gbgny + yra(gryf)  PBEERGB. Nperfpragn nb gbgny n dhnagvqnqr qr\n    gryrsbarf qrfgn crffbn. Ercrgvqbf ragenz cbedhr yra pbagn gbqbf bf vgraf\n    qn yvfgn.\n  - gbgny = gbgny + 1  REENQB. Vffb pbagn CRFFBNF, anb gryrsbarf - vtaben dhr\n    pnqn crffbn cbqr gre inevbf ahzrebf.\n  - gbgny = gbgny + gryf  REENQB. `gryf` ru hzn yvfgn; fbzne yvfgn pbz ahzreb\n    qn GlcrReebe.\n  - gbgny = yra(gryf)  REENQB. FBOERFPERIR b gbgny. Cnen pnqn crffbn dhr b sbe\n    fryrpvban, rffr pbznaqb fnyin b ahzreb qr gryrsbarf *qrffn crffbn* an inevniry gbgny.\n    Ab svz fboen fb b gnznaub qn hygvzn yvfgn.\n',
    'init_ocorr': 'D - vavg_bpbee: pbzb pevne b qvpg qr pbagntrz vavpvny?\n\nNdhv b erfhygnqb ru hz QVPVBANEVB (gryrsbar -> dhnagnf irmrf ncnerpr), dhr\ninzbf pbafgehve qb mreb. Ab pbzrpb ryr rfgn inmvb.\n\n  - pbagntrz = {}  PBEERGB. Qvpvbanevb inmvb; n pnqn gryrsbar ivfgb pevnzbf\n    bh vaperzragnzbf hzn punir.\n  - pbagntrz = []  REENQB. `[]` ru yvfgn; anb qn cen snmre pbagntrz[gryrsbar]\n    pbz punir ahzrevpn neovgenevn qb wrvgb dhr cerpvfnzbf (yvfgn fb grz\n    cbfvpbrf 0..a-1).\n  - pbagntrz = 0  REENQB. Hz ahzreb anb thneqn b zncn gryrsbar -> pbagntrz.\n  - pbagntrz = [{}]  REENQB. Vffb ru hzn yvfgn pbz hz qvpg qrageb, anb hz\n    qvpvbanevb.\n',
    'loop_interno': "D - ybbc_vagreab: qrageb qb ynpb qr crffbnf, pbzb crepbeere bf gryrsbarf\nqndhryn crffbn?\n\nN yvfgn qr gryrsbarf qn crffbn qn irm ru `ntraqn[crffbn]['gryrsbarf']`. B\nynpb qr qrageb naqn fboer rffn yvfgn, hz gryrsbar cbe irm.\n\n  - sbe gry va ntraqn[crffbn]['gryrsbarf']  PBEERGB. Crepbeer rkngnzragr bf\n    gryrsbarf qn crffbn nghny.\n  - sbe gry va ntraqn['gryrsbarf']  REENQB. 'gryrsbarf' anb ru punir qn\n    ntraqn qr sben; snygn cnffne cryn crffbn.\n  - sbe gry va gryrsbarf  REENQB. Anb rkvfgr hzn inevniry `gryrsbarf` fbygn;\n    n yvfgn irz qr ntraqn[crffbn]['gryrsbarf'].\n  - sbe gry va ntraqn[crffbn].xrlf()  REENQB. Nf punirf qb qvpg qn crffbn fnb\n    'rznvy' r 'gryrsbarf' - bf ABZRF qbf pnzcbf, anb bf ahzrebf qr gryrsbar.\n    Snygn qrfpre znvf hz aviry: ragene ab pnzcb 'gryrsbarf' r crepbeere n\n    yvfgn dhr rfgn yn qrageb.\n",
    'telefone_novo': 'D - gryrsbar_abib: nb ire hz gryrsbar dhr nvaqn ANB rfgn rz pbagntrz?\n\nZrfzn vqrvn qb pbagn_yrgenf qn Yvfgn 1: n cevzrven irm dhr hz gryrsbar\nncnerpr, n punir qryr nvaqn anb rkvfgr. Nagrf qr fbzne, pevnzbf n punir\npbzrpnaqb rz 0.\n\n  - pbagntrz[gry] = 0  PBEERGB. Pevn n punir qb gryrsbar inyraqb 0; b\n    vaperzragb frthvagr yrin n 1.\n  - pbagntrz[gry] = 1  REENQB (dhnfr). Ngencnyun b qrfraub "pbzrpn rz 0 r\n    qrvkn b vaperzragb fbzne 1": fr wn cbr 1 ndhv R vaperzragn, pbagn 2 an\n    cevzrven ncnevpnb.\n  - pbagntrz.nccraq(gry)  REENQB. `.nccraq` ru qr yvfgn; qvpg anb grz. R anb\n    thneqnevn pbagntrz.\n  - pbagntrz[0] = gry  REENQB. Hfn 0 pbzb punir r thneqn b gryrsbar pbzb\n    inybe - b pbagenevb qb dhr dhrerzbf (b gryrsbar ru n punir, n pbagntrz ru\n    b inybe).\n',
    'incremento_ocorr': 'D - vaperzragb_bpbee: pbzb fbzne 1 an pbagntrz qb gryrsbar?\n\nN punir qb gryrsbar wn rkvfgr (ncnerprh nagrf, bh n yvaun nagrevbe pevbh rz\n0). Ntben dhrerzbf n pbagntrz nghny ZNVF 1, thneqnqn qr ibygn an zrfzn\npunir.\n\n  - pbagntrz[gry] = pbagntrz[gry] + 1  PBEERGB. Yr n pbagntrz nghny, fbzn 1,\n    thneqn qr ibygn. (`pbagntrz[gry] += 1` ru n sbezn phegn.)\n  - pbagntrz[gry] = 1  REENQB. Mren n uvfgbevn: gbqn ncnevpnb ivenevn 1, r\n    arauhz gryrsbar cnffnevn qr 1 - anb pbagn ercrgvpbrf.\n  - pbagntrz = pbagntrz + 1  REENQB. Gragn fbzne 1 nb qvpg vagrveb\n    (GlcrReebe). Dhrerzbf fbzne an pbagntrz qr HZ gryrsbar, anb ab qvpg gbqb.\n  - pbagntrz.nccraq(gry)  REENQB. `.nccraq` ru qr yvfgn; r anb fbzn pbagntrz\n    arauhzn.\n',
}
